import path from 'path';
import fs from 'fs';
import { defineConfig, loadEnv } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig(({ mode }) => {
  const env = loadEnv(mode, '.', '');

  // Local HTTPS certs (generated by mkcert) — only used in development.
  // In production (Vercel / Netlify) TLS is terminated by the platform, so we skip these.
  const certPath = './localhost+2.pem';
  const keyPath  = './localhost+2-key.pem';
  const hasLocalCerts = fs.existsSync(certPath) && fs.existsSync(keyPath);
  const httpsConfig = hasLocalCerts
    ? { key: fs.readFileSync(keyPath), cert: fs.readFileSync(certPath) }
    : undefined; // let the platform handle TLS in production

  return {
    server: {
      port: 3000,
      host: true,
      https: httpsConfig,
    },
    plugins: [react()],
    assetsInclude: ['**/*.glb', '**/*.obj'],
    define: {
      'process.env.API_KEY': JSON.stringify(env.GEMINI_API_KEY),
      'process.env.GEMINI_API_KEY': JSON.stringify(env.GEMINI_API_KEY)
    },
    resolve: {
      alias: {
        '@': path.resolve(__dirname, '.'),
      }
    }
  };
});
